<?php
if (!defined('ROUTER_LOADED')) { http_response_code(403); exit('Accès direct interdit.'); }
if (!userCan($user, 'caisse.operations')) { http_response_code(403); echo '<div class="rounded-md border border-red-200 bg-red-50 p-4 text-red-700">Accès refusé.</div>'; return; }
require_once __DIR__ . '/../../api/database.php'; require_once __DIR__ . '/_sales.php';
$db=Database::getInstance();$errors=[];$operationType=(string)($_POST['operation_type']??'entree');$amountValue=trim((string)($_POST['amount']??''));$motive=trim((string)($_POST['motive']??''));$expenseCategory=trim((string)($_POST['expense_category']??''));$reference=trim((string)($_POST['reference']??''));$categories=array_column($db->fetchAll('SELECT category FROM cat_expens WHERE status = 1 ORDER BY category'),'category');
receptionEnsureCsrf();
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!hash_equals($_SESSION['csrf_token'],(string)($_POST['csrf_token']??'')))$errors[]='Le formulaire a expiré. Rechargez la page puis réessayez.';
    if(!in_array($operationType,['entree','sortie'],true))$errors[]='Type d’opération invalide.';
    if(!is_numeric($amountValue)||!is_finite((float)$amountValue)||(float)$amountValue<=0||round((float)$amountValue)!==(float)$amountValue)$errors[]='Le montant doit être un nombre entier positif en FBu.';
    if($motive===''||mb_strlen($motive)>255||mb_strlen($reference)>100)$errors[]='Le motif est obligatoire (255 caractères maximum).';
    if($operationType==='sortie'&&$expenseCategory!==''&&!in_array($expenseCategory,$categories,true)&&$expenseCategory!=='Autre')$errors[]='Choisissez une catégorie de dépense valide.';
    if(!$errors){$amount=(int)$amountValue;$pdo=$db->getPdo();try{$pdo->beginTransaction();$register=receptionEnsureOpenCashRegister($db,$user['nom_complet']);
        if($operationType==='entree'){
            $cashReference=$reference!==''?$reference:'REC-'.$register['id'].'-'.strtoupper(bin2hex(random_bytes(3)));
            $db->execute('INSERT INTO cash_in (trans_motive,amount,operator,date_created,reference) VALUES (?,?,?,?,?)',[mb_substr($motive,0,50),$amount,$user['nom_complet'],date('Y-m-d'),$cashReference]);
            $db->execute('UPDATE caisse SET montant_in = montant_in + ? WHERE id = ?',[$amount,$register['id']]);
            receptionRecordFinancialTransaction($db,$user['nom_utilisateur'],'Entrée de caisse',$cashReference,$amount,'entrée');
            $flashText='Entrée de caisse enregistrée : +'.number_format($amount,0,',',' ').' FBu.';
        }else{
            if((float)$db->fetchColumn('SELECT balance FROM caisse WHERE id = ?',[$register['id']])<$amount)throw new RuntimeException('Solde insuffisant dans la caisse du jour.');
            $expenseCategory=$expenseCategory!==''?$expenseCategory:'Frais divers';
            $cashReference=$reference!==''?$reference:'DEP-'.$register['id'].'-'.strtoupper(bin2hex(random_bytes(3)));
            $db->execute('INSERT INTO cash_out (user_id,amount,reason,status,cashout_type) VALUES (?,?,?,1,?)',[$user['nom_utilisateur'],$amount,$motive,$expenseCategory]);
            $db->execute('UPDATE caisse SET montant_out = montant_out + ? WHERE id = ?',[$amount,$register['id']]);
            $db->execute('INSERT INTO expenses (amount,expense_cat,purpose,id_proof,operator,date,status) VALUES (?,?,?,?,?,CURDATE(),\'Active\')',[$amount,$expenseCategory,$motive,$cashReference,$user['nom_complet']]);
            receptionRecordFinancialTransaction($db,$user['nom_utilisateur'],'Sortie de caisse - '.$expenseCategory,$cashReference,$amount,'sortie');
            $flashText='Sortie de caisse enregistrée : −'.number_format($amount,0,',',' ').' FBu.';
        }
        $pdo->commit();$_SESSION['flash_message']=['type'=>'success','text'=>$flashText];header('Location: '.app_route_url('caisse/operations'));exit;
    }catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();error_log('Reception cash operation failed: '.$error->getMessage());$errors[]=$error instanceof RuntimeException?$error->getMessage():'L’opération n’a pas été enregistrée.';}}
}
$register=$db->fetch('SELECT date,initial,montant_in,montant_out,balance,status FROM caisse WHERE date = CURDATE() LIMIT 1');
$recent=$db->fetchAll("SELECT date_created AS op_date,'Entrée' AS op_type,reference AS reference,trans_motive AS description,amount FROM cash_in WHERE date_created = CURDATE() UNION ALL SELECT created_at AS op_date,'Sortie' AS op_type,CAST(id AS CHAR) AS reference,COALESCE(reason,cashout_type) AS description,amount FROM cash_out WHERE created_at = CURDATE() ORDER BY op_date DESC LIMIT 10");
?>
<section class="mx-auto max-w-5xl space-y-5"><header><p class="text-sm font-semibold text-amber-800">Réception & caisse</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Entrées et sorties de caisse</h1><p class="mt-1 text-sm text-slate-600">Cette page enregistre des mouvements financiers manuels; les ventes de produits passent par Vente comptoir.</p></header>
<?php if($errors):?><div role="alert" class="rounded-md border border-red-200 bg-red-50 p-4 text-sm text-red-800"><ul class="list-disc space-y-1 pl-5"><?php foreach(array_unique($errors) as $error):?><li><?=receptionEscape($error)?></li><?php endforeach;?></ul></div><?php endif;?>
<div class="grid gap-3 sm:grid-cols-3"><article class="rounded-md border bg-white p-4"><p class="text-sm text-slate-500">Caisse du jour</p><p class="mt-1 font-semibold"><?=$register?((int)$register['status']===0?'Ouverte':'Fermée'):'Non ouverte'?></p></article><article class="rounded-md border bg-white p-4"><p class="text-sm text-slate-500">Solde disponible</p><p class="mt-1 text-xl font-bold"><?=number_format((float)($register['balance']??0),0,',',' ')?> FBu</p></article><article class="rounded-md border bg-white p-4"><p class="text-sm text-slate-500">Entrées / sorties du jour</p><p class="mt-1 text-sm font-semibold"><span class="text-green-800">+<?=number_format((float)($register['montant_in']??0),0,',',' ')?></span> / <span class="text-rose-700">−<?=number_format((float)($register['montant_out']??0),0,',',' ')?></span> FBu</p></article></div>
<form method="post" class="space-y-5 rounded-md border border-slate-200 bg-white p-5 sm:p-6"><input type="hidden" name="csrf_token" value="<?=receptionEscape($_SESSION['csrf_token'])?>"><fieldset class="grid gap-4 sm:grid-cols-2"><legend class="mb-2 text-sm font-semibold">Nouvelle opération</legend><label class="space-y-1 text-sm font-medium">Type<select name="operation_type" id="cashOperationType" class="w-full rounded-md border border-slate-300 bg-white px-3 py-2.5"><option value="entree" <?=$operationType==='entree'?'selected':''?>>Entrée de caisse</option><option value="sortie" <?=$operationType==='sortie'?'selected':''?>>Sortie de caisse / dépense</option></select></label><label class="space-y-1 text-sm font-medium">Montant (FBu)<input name="amount" type="number" min="1" step="1" required value="<?=receptionEscape($amountValue)?>" class="w-full rounded-md border border-slate-300 px-3 py-2.5 font-normal"></label><label class="space-y-1 text-sm font-medium">Motif<input name="motive" maxlength="255" required value="<?=receptionEscape($motive)?>" placeholder="Ex. remboursement, achat fournitures" class="w-full rounded-md border border-slate-300 px-3 py-2.5 font-normal"></label><label id="expenseCategoryField" class="space-y-1 text-sm font-medium">Catégorie dépense<select name="expense_category" class="w-full rounded-md border border-slate-300 bg-white px-3 py-2.5 font-normal"><option value="">Frais divers</option><?php foreach($categories as $category):?><option value="<?=receptionEscape($category)?>" <?=$expenseCategory===$category?'selected':''?>><?=receptionEscape($category)?></option><?php endforeach;?><option value="Autre" <?=$expenseCategory==='Autre'?'selected':''?>>Autre</option></select></label><label class="space-y-1 text-sm font-medium sm:col-span-2">Référence (facultatif)<input name="reference" maxlength="100" value="<?=receptionEscape($reference)?>" class="w-full rounded-md border border-slate-300 px-3 py-2.5 font-normal"></label></fieldset><div class="flex justify-end border-t pt-4"><button class="rounded-md bg-green-700 px-4 py-2.5 text-sm font-semibold text-white">Enregistrer le mouvement</button></div></form>
<section class="overflow-hidden rounded-md border border-slate-200 bg-white"><div class="border-b px-5 py-4"><h2 class="font-semibold">Opérations manuelles récentes</h2></div><div class="overflow-x-auto"><table class="min-w-full divide-y text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">Type</th><th class="px-4 py-3">Référence</th><th class="px-4 py-3">Motif</th><th class="px-4 py-3">Date</th><th class="px-4 py-3 text-right">Montant</th></tr></thead><tbody class="divide-y"><?php if(!$recent):?><tr><td colspan="5" class="px-4 py-8 text-center text-slate-500">Aucune opération manuelle aujourd’hui.</td></tr><?php else:foreach($recent as $op):?><tr><td class="px-4 py-3"><?=receptionEscape($op['op_type'])?></td><td class="px-4 py-3 font-mono text-xs"><?=receptionEscape($op['reference']??'—')?></td><td class="px-4 py-3"><?=receptionEscape($op['description'])?></td><td class="px-4 py-3"><?=receptionEscape(date('d/m/Y',strtotime($op['op_date'])))?></td><td class="px-4 py-3 text-right font-semibold"><?=number_format((float)$op['amount'],0,',',' ')?> FBu</td></tr><?php endforeach;endif;?></tbody></table></div></section></section>
<script>
(() => { const kind=document.getElementById('cashOperationType'); const category=document.getElementById('expenseCategoryField'); const update=()=>{category.hidden=kind.value!=='sortie';}; kind.addEventListener('change',update); update(); })();
</script>